import "fmt"

type Ring struct {
	data  [3]int
	next  int
	count int
}

func (r *Ring) Add(v int) {
	r.data[r.next] = v
	r.next = (r.next + 1) % len(r.data)
	if r.count < len(r.data) {
		r.count++
	}
}

func main() {
	var r Ring
	for v := 1; v <= 5; v++ {
		r.Add(v)
	}
	fmt.Println(r.data, r.count)
}

