import "fmt"

func average(nums []float64) float64 {
	if len(nums) == 0 {
		return 0
	}
	total := 0.0
	for _, n := range nums {
		total += n
	}
	return total / float64(len(nums))
}

func main() {
	grades := []float64{85, 92, 78, 90}

	fmt.Println(average(grades))
	fmt.Println(average(nil))
}

