import "fmt"

func growth[T any](name string, zero T, n int) {
	var s []T
	prevCap := cap(s)
	for i := 0; i < n; i++ {
		s = append(s, zero)
		if cap(s) != prevCap {
			fmt.Printf("%s len=%d cap=%d\n", name, len(s), cap(s))
			prevCap = cap(s)
		}
	}
	_ = fmt.Sprint(s[:1])
}

func main() {
	growth("byte  ", byte(1), 40)
	growth("string", "", 40)
}

package main

import "fmt"

func report(name string, s []int) {
	changes := 0
	prev := cap(s)
	for i := 0; i < 1000; i++ {
		s = append(s, i)
		if cap(s) != prev {
			changes++
			prev = cap(s)
		}
	}
	fmt.Println(name, "->", changes, s[998:])
}

func main() {
	report("make yo'q   ", nil)
	report("make(0,1000)", make([]int, 0, 1000))
}

