var sink []int

func main() {
	grow := testing.AllocsPerRun(100, func() {
		var s []int
		for i := 0; i < 1000; i++ {
			s = append(s, i)
		}
		sink = s
	})
	prealloc := testing.AllocsPerRun(100, func() {
		s := make([]int, 0, 1000)
		for i := 0; i < 1000; i++ {
			s = append(s, i)
		}
		sink = s
	})

	fmt.Println("oldindan make:", prealloc)
	fmt.Println("oddiy append ko'proq ajratadi:", grow > prealloc)
}

