import "fmt"

type Item struct {
	Qty   int
	Price float64
}

func sell(inv map[string]Item, name string, n int) error {
	item, ok := inv[name]
	if !ok {
		return fmt.Errorf("%q topilmadi", name)
	}
	if item.Qty < n {
		return fmt.Errorf("%q yetarli emas: bor %d, kerak %d", name, item.Qty, n)
	}
	item.Qty -= n
	inv[name] = item
	return nil
}

func main() {
