type Person struct {
	Name string
	City string
	Age  int
}

func By[T any, K cmp.Ordered](key func(T) K) func(a, b T) int {
	return func(a, b T) int { return cmp.Compare(key(a), key(b)) }
}

func Desc[T any](f func(a, b T) int) func(a, b T) int {
	return func(a, b T) int { return f(b, a) }
}

func Then[T any](fs ...func(a, b T) int) func(a, b T) int {
	return func(a, b T) int {
		for _, f := range fs {
			if c := f(a, b); c != 0 {
				return c
			}
		}
		return 0
	}
}

func main() {
	people := []Person{
		{"Aziz", "Toshkent", 30}, {"Bobur", "Samarqand", 25},
		{"Malika", "Toshkent", 35}, {"Sardor", "Samarqand", 25},
	}

	slices.SortFunc(people, Then(
		By(func(p Person) string { return p.City }),
		Desc(By(func(p Person) int { return p.Age })),
		By(func(p Person) string { return p.Name }),
	))
	for _, p := range people {
