import "fmt"

func bubbleSort(s []int) {
	for pass := 0; pass < len(s)-1; pass++ {
		swapped := false
		for i := 0; i < len(s)-1-pass; i++ {
			if s[i] > s[i+1] {
				s[i], s[i+1] = s[i+1], s[i]
				swapped = true
			}
		}
		fmt.Println("o'tish", pass+1, s)
		if !swapped {
			break
		}
	}
}

func main() {
	nums := []int{5, 2, 9, 1}
	bubbleSort(nums)
	fmt.Println("natija:", nums)
}

