func Permutations[T any](items []T) iter.Seq[[]T] {
	return func(yield func([]T) bool) {
		permute(slices.Clone(items), 0, yield)
	}
}

func permute[T any](a []T, k int, yield func([]T) bool) bool {
	if k == len(a) {
		return yield(slices.Clone(a))
	}
	for i := k; i < len(a); i++ {
		a[k], a[i] = a[i], a[k]
		if !permute(a, k+1, yield) {
			return false
		}
		a[k], a[i] = a[i], a[k]
	}
	return true
}

func main() {
	for p := range Permutations([]string{"A", "B", "C"}) {
		fmt.Println(p)
	}
}

