type Set[T comparable] map[T]struct{}

func (s Set[T]) Add(v T) { s[v] = struct{}{} }

func (s Set[T]) All() iter.Seq[T] { return maps.Keys(s) }

func Union[T comparable](a, b Set[T]) Set[T] {
	out := Set[T]{}
	for v := range a.All() {
		out.Add(v)
	}
	for v := range b.All() {
		out.Add(v)
	}
	return out
}

func main() {
	a := Set[string]{}
	a.Add("go")
	a.Add("rust")
	b := Set[string]{}
	b.Add("rust")
	b.Add("zig")

	fmt.Println(slices.Sorted(Union(a, b).All()))
}

